#!/usr/bin/env python3
"""Exact-device proof of storage children generated by compiler forward AD."""
import argparse
import ctypes as ct
import hashlib
import json
from pathlib import Path
import sys
import subprocess
from types import SimpleNamespace
import numpy as np
ROOT = Path(__file__).resolve().parents[1]
sys.path[:0] = [str(ROOT), str(ROOT / 'python')]
import tessera as ts  # noqa: E402
from benchmarks.record_device_ring_protocol import Device  # noqa: E402
from tessera.compiler.native_jvp import NativeJVPArtifact  # noqa: E402
from tessera.compiler.native_storage_jvp import NativeStorageJVP  # noqa: E402


@ts.jit(autodiff='forward')
def sigmoid(x):
    return ts.ops.sigmoid(x)


@ts.jit(autodiff='forward')
def tanh(x):
    return ts.ops.tanh(x)


@ts.jit(autodiff='forward')
def composed(x):
    return ts.ops.sigmoid(ts.ops.tanh(x))


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--backend', choices=['nvidia', 'rocm'], required=True)
    p.add_argument('--compiler', type=Path, required=True)
    p.add_argument('--output', type=Path, required=True)
    args = p.parse_args()
    device = Device(args.backend)
    rows = []
    for family, function in [('sigmoid', sigmoid), ('tanh', tanh), ('composed', composed)]:
        for width in [32, 64, 256]:
            x = np.linspace(-12, 12, width, dtype=np.float32)
            x[:12] = [-np.inf, -1000, -100, -1e-7, -0.0, 0.0, 1e-7, 100, 1000, np.inf, np.nan, 1]
            dx = (np.arange(width, dtype=np.float32) % 7 - 3) / 8
            examples = (x,)
            arrays = [x, dx, np.zeros_like(x), np.zeros_like(x)]
            artifact = function.compile_native_storage_jvp(*examples, compiler=args.compiler,
                llvm_bin=Path('/usr/lib/llvm-23/bin'), backend=args.backend,
                chip='sm_120' if device.cuda else 'gfx1151')
            # Reload the compiler product, including its serialized pinned child.
            pair = NativeStorageJVP(NativeJVPArtifact(json.loads(json.dumps(artifact.contract))))
            pointers = []
            tensors = []
            try:
                for a in arrays:
                    ptr = ct.c_void_p()
                    device.check(device.alloc(ct.byref(ptr), a.nbytes))
                    pointers.append(ptr)
                    device.check(device.htod(ptr, a.ctypes.data, a.nbytes) if device.cuda else device.copy(ptr, a.ctypes.data, a.nbytes, 1))
                    tensors.append(SimpleNamespace(__cuda_array_interface__=dict(version=3, shape=a.shape,
                        typestr=a.dtype.str, data=(ptr.value, False))))
                outputs = pair(*tensors, width)
                assert outputs == (tensors[-2], tensors[-1])
                for a, ptr in zip(arrays[-2:], pointers[-2:]):
                    device.check(device.dtoh(a.ctypes.data, ptr, a.nbytes) if device.cuda else device.copy(a.ctypes.data, ptr, a.nbytes, 2))
                def stable_sigmoid(z):
                    e = np.exp(-np.abs(z))
                    return np.where(z < 0, e / (1 + e), 1 / (1 + e))
                z = x.astype(np.float64)
                if family == 'tanh':
                    primal = np.tanh(z)
                    tangent = dx * (1 - primal * primal)
                elif family == 'sigmoid':
                    primal = stable_sigmoid(z)
                    tangent = dx * primal * (1 - primal)
                else:
                    t = np.tanh(z)
                    primal = stable_sigmoid(t)
                    tangent = dx * (1 - t*t) * primal * (1-primal)
                np.testing.assert_allclose(arrays[-2], primal, atol=2e-6, rtol=2e-6, equal_nan=True)
                np.testing.assert_allclose(arrays[-1], tangent, atol=2e-6, rtol=2e-6, equal_nan=True)
                if family == 'tanh':
                    np.testing.assert_allclose(arrays[-2][3:7], primal[3:7], atol=0, rtol=2e-6)
                    assert np.signbit(arrays[-2][4]) and not np.signbit(arrays[-2][5])
                rows.append(dict(family=family, width=width, primal='atol=rtol=2e-6', tangent='atol=rtol=2e-6', artifact_hash=artifact.artifact_hash,
                    source_graph_ir_digest=artifact.contract['source_graph_ir_digest'],
                    paired_jvp_ir_digest=artifact.contract['paired_jvp_ir_digest'],
                    child_digest=artifact.contract['steps'][0]['child_digest']))
            finally:
                pair.close()
                for ptr in pointers:
                    device.check(device.free(ptr))
    args.output.write_text(json.dumps(dict(backend=args.backend, device=(subprocess.check_output(
        ['nvidia-smi', '--query-gpu=name,uuid,driver_version', '--format=csv,noheader'] if device.cuda
        else ['/opt/rocm/bin/rocminfo'], text=True)), runtime_sources={str(p): hashlib.sha256((ROOT/p).read_bytes()).hexdigest() for p in
        ['python/tessera/compiler/jit.py','python/tessera/compiler/native_storage_jvp.py','python/tessera/compiler/native_gpu_storage.py','python/tessera/compiler/native_gpu_tensor.py']}, compiler_sha256=hashlib.sha256(args.compiler.read_bytes()).hexdigest(),
        recorder_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(), rows=rows,
        boundary='rank-one f32 nonlinear forward products including tails, signed zero and NaN; no reverse AD or performance claim'), indent=2)+'\n')
    print(json.dumps(rows, indent=2))


if __name__ == '__main__':
    main()
